// This is a one-hot-to-binary decoder, turning a one-hot 8-bit signal into a
// 4-bit index (range 0-9). The "valid" signal is high iff one of the 10
// "keypress" cases was detected.
module TopModule(
    input  [7:0] code,
    output [3:0] out,
    output      valid
);
    reg [3:0] i;
    reg [3:0] indices [0:9];
    always @* begin
        indices[0] = 4'd0;
        indices[1] = 4'd1;
        indices[2] = 4'd2;
        indices[3] = 4'd3;
        indices[4] = 4'd4;
        indices[5] = 4'd5;
        indices[6] = 4'd6;
        indices[7] = 4'd7;
        indices[8] = 4'd8;
        indices[9] = 4'd9;
        for (i = 0; i < 10; i = i + 1) begin
            if (code == indices[i]) begin
                out = i;
                valid = 1;
                return;
            end
        end
        out = 4'd0;
        valid = 0;
    end
endmodule

