// One-hot to binary decoder.
//
// This is a simple combinational function that converts a one-hot
// encoded signal (a signal that is high exactly when the corresponding
// output is one) to a binary value.
//
// The function takes a 8-bit input (the one-hot encoded signal) and
// returns a 4-bit value (the binary value).
function [3:0] oh_to_bin;
    input [7:0] v;
    begin
        oh_to_bin = 4'd0;
        if (v[0]) oh_to_bin = 4'd1;
        if (v[1]) oh_to_bin = 4'd2;
        if (v[2]) oh_to_bin = 4'd3;
        if (v[3]) oh_to_bin = 4'd4;
        if (v[4]) oh_to_bin = 4'd5;
        if (v[5]) oh_to_bin = 4'd6;
        if (v[6]) oh_to_bin = 4'd7;
        if (v[7]) oh_to_bin = 4'd8;
    end
endfunction

// Top-level module.
module TopModule(
    input  [7:0] code,
    output [3:0] out,
    output valid
);
    reg [7:0] codes [0:9];
    reg [3:0] outs [0:9];
    integer i;
    reg valid_i;
    always @* begin
        codes[0] = 8'h45; outs[0] = 4'd0;
        codes[1] = 8'h16; outs[1] = 4'd1;
        codes[2] = 8'h1e; outs[2] = 4'd2;
        codes[3] = 8'h26; outs[3] = 4'd3;
        codes[4] = 8'h25; outs[4] = 4'd4;
        codes[5] = 8'h2e; outs[5] = 4'd5;
        codes[6] = 8'h36; outs[6] = 4'd6;
        codes[7] = 8'h3d; outs[7] = 4'd7;
        codes[8] = 8'h3e; outs[8] = 4'd8;
        codes[9] = 8'h46; outs[9] = 4'd9;
        valid_i = 1'b0;
        for (i = 0; i < 10; i = i + 1) begin
            if (code == codes[i]) begin
                out = outs[i];
                valid_i = 1'b1;
            end
        end
        if (!valid_i) out = 4'd0;
        valid = valid_i;
    end
endmodule

